import {adjustedIncomeSource as source} from './planning-adjusted-income-data.js';
export const adjustedIncomeDefinitions={
  adjustedIncome:{title:'Compare two income concepts in one historical release snapshot',fields:[
    ['adjustedYear','Annual reference year (2021–2025)',2025,2021,2025,1],
    ['adjustedGroup','Income group to trace: 1 lowest, 3 middle, 5 highest',3,1,5,1]
  ]}
};
export function adjustedIncomeSelection(input){
  const group=source.groups[input.adjustedGroup-1],row=group.rows.find(r=>r.year===input.adjustedYear);
  return {group,row,share:row.inKind/row.adjusted};
}
export function adjustedIncomeResult(kind,input){
  if(kind!=='adjustedIncome')throw Error('Unknown adjusted-income topic.');
  const {group,row}=adjustedIncomeSelection(input),current=source.groups.map(g=>({...g,row:g.rows.find(r=>r.year===input.adjustedYear)}));
  const common={source:source.url,sourceLabel:'Statistics Canada · Table 36-10-0587-01 · 13 April 2026 release snapshot'};
  const bridge=[{label:'Published household disposable-income mean',value:row.disposable},{label:'Published social transfers in kind mean',value:row.inKind},...(row.roundingResidual?[{label:'Published whole-dollar rounding residual',value:row.roundingResidual}]:[])];
  return {metrics:[['Selected group · household disposable income',row.disposable,'money'],['Selected group · social transfers in kind',row.inKind,'money'],['Selected group · adjusted household disposable income',row.adjusted,'money']],note:'All values are annual national-accounts group means in current CAD per household, from one public 13 April 2026 vintage, covering 2021–2025. The 75 selected observations use Canada, “Value per household,” five income quintiles and three canonical measures. They are not medians, personal salary thresholds, bank deposits, account balances or inflation-adjusted dollars. Income quintiles are assigned using equivalized household disposable income; the plotted values are per household, not per consumption unit. Social transfers in kind are added service and goods value, not an extra general-purpose cash transfer. Same-named same-named entries were reconciled and not counted twice. Four of the 25 published income identities differ by CAD 1 because values are rounded to whole dollars; the bridge preserves that residual. No missing or flagged observation was filled with zero.',charts:[
    {id:'adjusted-income-levels',type:'groupbar',title:'Two income concepts for the same five groups in '+input.adjustedYear,unit:'money',unitLabel:'Current CAD per household per year · group means',seriesNames:['Household disposable income','Adjusted household disposable income'],rows:current.map(g=>({label:g.label,values:[g.row.disposable,g.row.adjusted]})),...common,note:'The second measure adds social transfers in kind to the first, subject to published rounding. Both bars are nominal annual means for the same source income group. Neither is a household’s actual take-home-pay deposit. “Adjusted” here describes the in-kind resource adjustment, not an inflation adjustment.'},
    {id:'adjusted-income-in-kind',type:'bar',title:'The published non-cash component has its own dollar amount',unit:'money',unitLabel:'Social transfers in kind · current CAD per household per year',rows:current.map(g=>({label:g.label,value:g.row.inKind})),...common,note:'These are allocated national-accounts means for goods and services financed by governments and non-profit institutions serving households. They are not cash benefits payable to every household, an individual medical bill, an education voucher or the amount a person could withdraw. Source methodology uses distribution information and proxies.'},
    {id:'adjusted-income-history',type:'line',title:group.label+': follow both published annual means',unit:'money',unitLabel:'Current CAD per household per year · one release vintage',xLabel:'Calendar year',xTicks:[0,2,4].map(index=>({value:index,label:String(source.years[index])})),series:[['Household disposable income','disposable'],['Adjusted household disposable income','adjusted']].map(([name,key],i)=>({name,dash:i===1,rows:group.rows.map((r,index)=>({x:index,label:String(r.year),value:r[key]}))})),...common,note:'The five points are 2021 through 2025, with exact dates and means in the table. Changing the income-group control selects a different history. Changing the selected year leaves this complete history unchanged. Lines connect changing group averages, not the same families followed through time; movements are nominal and no causal explanation is inferred.'},
    {id:'adjusted-income-identity',type:'waterfall',title:'Reconcile the selected '+input.adjustedYear+' adjusted-income mean',unit:'money',unitLabel:'Current CAD per household per year · selected income group',rows:bridge,totalLabel:'Published adjusted disposable-income mean',...common,evidence:'Derived from official statistics',note:'Published disposable income plus published social transfers in kind gives the adjusted concept, allowing for independent whole-dollar rounding. A residual row appears only where needed to reproduce the published endpoint. It is a rounding reconciliation, not another economic benefit or cash payment. The selected source in-kind series is included exactly once.'},
    {id:'adjusted-income-relative-scatter',type:'scatter',title:'Similar non-cash amounts can represent different shares of adjusted income',unit:'percent',xUnit:'money',unitLabel:'One point per income group · annual published means and a derived ratio',xLabel:'Disposable income (CAD)',yLabel:'In-kind transfers / adjusted income',pointLabelHeader:'Income quintile',pointContext:'The larger filled point marks the selected income group; hollow points mark the other groups. Each point combines published annual group means with a ratio calculated from those means. Points are not individual households or simulated investment outcomes.',labelLeaders:true,rows:current.map((g,index)=>({label:g.short,x:g.row.disposable,value:g.row.inKind/g.row.adjusted,selected:index+1===input.adjustedGroup,annotate:index===0||index===4})),...common,evidence:'Derived from official statistics',note:'Horizontal position is the ordinary disposable-income mean. Vertical position is published social transfers in kind divided by the adjusted-income mean for the same group and year. This is a ratio of group means, not the average of individual household percentages or a share of cash pay. Both measures describe aggregate groups; no correlation test or individual prediction is supplied.'}
  ]};
}
